"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["22009"],{52053(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada","status":422,"titulo":"A defini\xe7\xe3o do fato de sistema \xe9 travada: s\xf3 o nome, a descri\xe7\xe3o e a prote\xe7\xe3o de dados se editam"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada","requisitos":["UNI-REQ-0143","UNI-REQ-0205","UNI-REQ-0207"],"oQueAconteceu":["Os fatos de sistema s\xe3o definidos pela lei ou calculados pelo pr\xf3prio Uni+. O c\xf3digo, o tipo de dado, se aceita um ou v\xe1rios valores, a origem, a fonte e o formato dos valores, os valores do dom\xednio, as regras padr\xe3o, o ponto em que o valor fica conhecido, o escopo e a ativa\xe7\xe3o continuam travados. A opera\xe7\xe3o pedida mexe em algum deles: a altera\xe7\xe3o da defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) com um eixo diferente do que o fato j\xe1 tem, a defini\xe7\xe3o das regras padr\xe3o (`PUT .../{id}/regras-padrao`), a desativa\xe7\xe3o (`DELETE .../{id}`) e a reativa\xe7\xe3o (`POST .../{id}/ativacao`) do fato, e o acr\xe9scimo, a corre\xe7\xe3o, a reordena\xe7\xe3o, a desativa\xe7\xe3o e a reativa\xe7\xe3o de valores (`.../{id}/valores`, `.../{id}/ordem-dos-valores`). Um eixo reenviado com o mesmo valor que o fato j\xe1 tem n\xe3o conta como altera\xe7\xe3o.","A busca do fato vem antes ([fato do candidato n\xe3o encontrado](/erros/uniplus.configuracao.fato_candidato.nao_encontrado)). Um valor de eixo fora do vocabul\xe1rio (dom\xednio, cardinalidade, escopo, fonte dos valores ou formato) \xe9 recusado antes desta recusa, como erro do pr\xf3prio campo. A resposta n\xe3o traz a lista `errors`: a recusa \xe9 do fato, e n\xe3o de um campo. Nada \xe9 gravado."],"comoResolver":["Altere s\xf3 o nome, a descri\xe7\xe3o, a forma de exibi\xe7\xe3o ou a prote\xe7\xe3o de dados (classifica\xe7\xe3o, finalidade e base legal). A mudan\xe7a da prote\xe7\xe3o deixa o fato pendente at\xe9 a aprova\xe7\xe3o da prote\xe7\xe3o de dados."],"ondeAparece":["Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo","Defini\xe7\xe3o das regras padr\xe3o de um fato derivado por regra","Desativa\xe7\xe3o de um fato do cat\xe1logo","Reativa\xe7\xe3o de um fato do cat\xe1logo","Acr\xe9scimo de um valor a um fato do cat\xe1logo","Corre\xe7\xe3o de um valor de um fato do cat\xe1logo","Reordena\xe7\xe3o dos valores de um fato do cat\xe1logo","Desativa\xe7\xe3o de um valor de um fato do cat\xe1logo","Reativa\xe7\xe3o de um valor de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);